char	*ft_strdup(const char *s1)
{
	char	*res = malloc(strlen(s1) + 1);

	if (!res)
		return (NULL);
	strcpy(res, s1);
	return (res);
}

char	*ft_substr(char const *s, unsigned int start, size_t len)
{
	char	*res;

	if (!s)
		return (NULL);
	if (start > strlen(s))
		return (ft_strdup(""));
	res = malloc(len + 1);
	if (!res)
		return (NULL);
	strncpy(res, s + start, len);
	res[len] = '\0';
	return (res);
}

char	*ft_strjoin(char const *s1, char const *s2)
{
	if (!s1 || !s2)
		return (NULL);
	char	*res = malloc(strlen(s1) + strlen(s2) + 1);
	if (!res)
		return (NULL);
	strcpy(res, s1);
	strcat(res, s2);
	return (res);
}

void	ft_putchar_fd(char c, int fd)
{
	write(fd, &c, 1);
}

void	ft_putstr_fd(char *s, int fd)
{
	if (s)
		write(fd, s, strlen(s));
}

void	ft_putendl_fd(char *s, int fd)
{
	ft_putstr_fd(s, fd);
	write(fd, "\n", 1);
}

t_list	*ft_lstnew(void *content)
{
	t_list	*res = malloc(sizeof(t_list));

	if (!res)
		return (NULL);
	res->content = content;
	res->next = NULL;
	return (res);
}

void	ft_lstadd_front(t_list **lst, t_list *new)
{
	if (lst && new)
	{
		new->next = *lst;
		*lst = new;
	}
}

int	ft_lstsize(t_list *lst)
{
	int	i = 0;

	while (lst)
	{
		lst = lst->next;
		i++;
	}
	return (i);
}

t_list	*ft_lstlast(t_list *lst)
{
	if (!lst)
		return (NULL);
	while (lst->next)
		lst = lst->next;
	return (lst);
}
